lc_case('Draft is only the pre-start state and cannot activate without a publication',function(){global $svc,$owned;$d=$svc->create(array('name'=>'Lifecycle draft'),'DRAFT_'.bin2hex(random_bytes(6)));$owned[]=$d['study_id'];pe_assert($d['lifecycle']['state']==='DRAFT');pe_reject(function()use($svc,$d){$svc->changeStudyState($d['id'],0,'ACTIVE',false,'NO_PUBLICATION');},'PUBLISHED_VERSION_REQUIRED');pe_assert($svc->load($d['id'])['lifecycle']['state']==='DRAFT');});
