lc_case('Finalization removes operational emails revokes all access and preserves saved science',function(){global $svc;$p=lc_publish(array('verification_policy'=>'ALLOW_UNVERIFIED'));$f=pf_enroll($p,'erase@example.test');$f=pf_runtime()->handle($p['public'],$f['token'],pe_request($f,'submit',array('R_q1'=>'respuesta conservada')));$cap=pf_mint($f);$before=lc_row($f);$e=lc_change($p,'FINALIZED');$after=lc_row($f);$participant=pf_participant($f);pe_assert($participant['email']===null&&$participant['archived_email']===null&&!$participant['active']);pe_assert($after['checkpoint_hash']===$before['checkpoint_hash']&&$after['seed_ciphertext']===$before['seed_ciphertext']&&$after['finalized_at']!==null);pe_reject(function()use($p,$f){pf_runtime()->handle($p['public'],$f['token']);},'STUDY_FINALIZED');pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'STUDY_FINALIZED');foreach(pf_intents($f['access']['execution_id']) as $intent)pe_assert($intent['state']==='CANCELLED');pe_assert(!pf_db()->row(pf_db()->prepare('SELECT id FROM '.pf_db()->table('enrollment_receipts').' WHERE execution_id=%s',$f['access']['execution_id'])));pe_reject(function()use($f){pf_owner()->dispatch($f['access']['execution_id'],array('id'=>'LATE','kind'=>'FIRST_ACCESS','expected_revision'=>0));},'STUDY_FINALIZED');$export=(new EIPSI\StudyEngine\Privacy\ExportAdapter(pf_db()))->dataset($p['definition']['study']['logical_id']);pe_assert(count($export['manifest'])===1,'Historical data omitted');pe_assert(in_array('respuesta conservada',array_column($export['rows'],'value'),true),'Saved response lost');pe_assert((new P\SubmissionJournalRepository(pf_db()))->list($f['access']['execution_id'])[0]['local_state']==='CONFIRMED','Storage journal changed');});
lc_case('Reopening keeps the public Study but the same email enrolls as a new subject',function(){global $svc;$p=lc_publish(array('verification_policy'=>'ALLOW_UNVERIFIED'));$old=pf_enroll($p,'same@example.test');lc_change($p,'FINALIZED');$new=lc_change($p,'REOPEN');pe_assert($new['lifecycle']['state']==='ACTIVE'&&$new['lifecycle']['cycle']===2);pe_assert($new['public_url']===$svc->load($p['version'])['public_url']);$f=pf_enroll($p,'same@example.test');pe_assert($f['access']['participant_id']!==$old['access']['participant_id']&&$f['access']['execution_id']!==$old['access']['execution_id']);pe_assert(lc_row($f)['study_cycle']==='2');pe_assert((new L\Identity(pf_db(),pf_clock()))->recover($p['public'],$old['token'])===null);});
lc_case('Retained email is historical only and a later erase removes earlier retained copies',function(){ $p=lc_publish(array('verification_policy'=>'ALLOW_UNVERIFIED'));$old=pf_enroll($p,'retained@example.test');lc_change($p,'FINALIZED',false);$r=pf_participant($old);pe_assert($r['email']===null&&$r['archived_email']==='retained@example.test');lc_change($p,'REOPEN');$next=pf_enroll($p,'retained@example.test');pe_assert($next['access']['participant_id']!==$old['access']['participant_id']);lc_change($p,'FINALIZED',true);pe_assert(pf_participant($old)['archived_email']===null&&pf_participant($next)['email']===null);});
lc_case('Closure covers participants pinned to every version and stale activation cannot bypass it',function(){global $svc;$p=lc_publish(array('verification_policy'=>'ALLOW_UNVERIFIED'));$a=pf_enroll($p);$q=pf_publish(null,array('verification_policy'=>'ALLOW_UNVERIFIED'),$p['definition']['study']['logical_id'],$p['public'],2);$b=pf_enroll($q);$summary=$svc->lifecycleSummary($p['version']);pe_assert($summary['participants']===2);$view=pf_owner()->view($a['access']['execution_id']);$expected=0;foreach(array($a,$b) as $frame){$action=$frame['view']['next_action'];if($action['kind']==='OPEN_ASSESSMENT'&&$frame['view']['snapshot']['instances'][$action['payload']['assessment_execution_id']]['state']==='IN_PROGRESS')$expected++;}pe_assert($summary['assessments_in_progress']===$expected,'Containers counted as assessments');lc_change($q,'FINALIZED');pe_assert(lc_row($a)['finalized_at']!==null&&lc_row($b)['finalized_at']!==null);pe_reject(function()use($p){(new R\PublicStudyRepository(pf_db()))->activate($p['version']);},'STUDY_FINALIZED');});
lc_case('Lifecycle requests replay safely and stale tabs cannot re-finalize a reopened cycle',function()use(&$replayed){global $svc;$p=lc_publish();$before=$svc->load($p['version']);$rev=$before['lifecycle']['revision'];$svc->changeStudyState($p['version'],$rev,'FINALIZED',true,'REPLAY_FINAL');$retry=$svc->changeStudyState($p['version'],$rev,'FINALIZED',true,'REPLAY_FINAL');pe_assert($retry['lifecycle']['revision']===$rev+1);lc_change($p,'REOPEN');$retry=$svc->changeStudyState($p['version'],$rev,'FINALIZED',true,'REPLAY_FINAL');pe_assert($retry['lifecycle']['state']==='ACTIVE');pe_reject(function()use($p,$rev,$svc){$svc->changeStudyState($p['version'],$rev,'FINALIZED',false,'STALE_FINAL');},'STUDY_STATE_CONFLICT');pe_reject(function()use($p,$rev,$svc){$svc->changeStudyState($p['version'],$rev,'FINALIZED',false,'REPLAY_FINAL');},'LIFECYCLE_REQUEST_REUSED');});
